let fila = [];
try {
  fila = $('Code - Montar Fila de Envios').all().map(i => i.json);
} catch (e) {
  fila = [];
}

const envios = fila.filter(f => f.TIPO_ENVIO === 'ALUNO' || f.TIPO_ENVIO === 'FORMADOR');
const cursos = [...new Set(envios.map(f => f.spreadsheetName))];

return [{
  json: {
    status: envios.length ? 'CONCLUIDO' : 'SEM_ENVIOS',
    cursos_processados: cursos.length,
    cursos,
    emails_alunos: envios.filter(f => f.TIPO_ENVIO === 'ALUNO').length,
    emails_formadores: envios.filter(f => f.TIPO_ENVIO === 'FORMADOR').length,
    mensagem: envios.length
      ? 'Fila processada na ordem: alunos e depois formadores, turma a turma.'
      : 'Nenhum e-mail para enviar na(s) data(s)-alvo.'
  }
}];
